function plot_switch_simulationwithdifferentparameters(input,rule_labels)
% % plot_switch_simulationwithdifferentparameters %
%PURPOSE:   Plot choice behavior around switches, pre vs post-lesion
%AUTHORS:   H Atilgan & AC Kwan May20
%
%INPUT ARGUMENTS
%   input:  Structure generated by choice_switch(), pre-lesion
%   input2: Structure generated by choice_switch(), post-lesion
%   tlabel: Text string that will be put on top of the figure
%   rule_labels:    Text strings for the legend in figure

%%

paramNum = numel(input);
n=input(1).sw_output.n;
numtransType=input(1).sw_output.numtransType;
transType=input(1).sw_output.transType;
cmap = flip(brewermap(paramNum+2,'Blues'));


for kk=1:paramNum
    for j=1:numel(input(kk).sw_output)
        temp_probl(:,:,j)=input(kk).sw_output.probl;
        temp_probr(:,:,j)=input(kk).sw_output.probr;
        temp_probn(:,:,j)=input(kk).sw_output.probneither;
    end
    dat(kk).probl=nanmean(temp_probl,3);
    dat(kk).probr=nanmean(temp_probr,3);
    dat(kk).probn=nanmean(temp_probn,3);
    dat(kk).probl_sem=nanstd(temp_probl,[],3)./sqrt(numel(input(kk).sw_output));
    dat(kk).probr_sem=nanstd(temp_probr,[],3)./sqrt(numel(input(kk).sw_output));
    dat(kk).probn_sem=nanstd(temp_probn,[],3)./sqrt(numel(input(kk).sw_output));
    dat(kk).color = cmap(kk,:);
    dat(kk).label = input(kk).legend;
    clearvars temp_probl temp_probr temp_probn;
end

figure;

for j=1:numtransType
    
    subplot(1,numtransType,j); hold on;
    
    legstring=[];
    legendNum = 1;
    
    %plot dotted line at trial = 0
    plot([0 0],[0 1],'k--','LineWidth',2);
    
    for kk=1:paramNum
        %plot the mean
        h(legendNum)=plot(n,dat(kk).probl(:,j),'-','MarkerSize',30,'Linewidth',3,'Color',dat(kk).color);
        legstring{legendNum}=['Left, ' dat(kk).label];
        legendNum = legendNum + 1;
        
        h(legendNum)=plot(n,dat(kk).probr(:,j),'-.','MarkerSize',30,'Linewidth',3,'Color',dat(kk).color);
        legstring{legendNum}=['Right, ' dat(kk).label];
        legendNum = legendNum + 1;
        
%         h(legendNum)=plot(n,dat(kk).probn(:,j),':','MarkerSize',30,'Linewidth',3,'Color',dat(kk).color);
%         legstring{legendNum}=['Miss, ' dat(kk).label];
%         legendNum = legendNum + 1;
%         
        %plot the error bars
%         for l=1:numel(n)
%             plot(n(l)*[1 1],dat(kk).probl(l,j)+dat(kk).probl_sem(l,j)*[-1 1],'-','LineWidth',3,'Color',dat(kk).color);
%             plot(n(l)*[1 1],dat(kk).probr(l,j)+dat(kk).probr_sem(l,j)*[-1 1],'-.','LineWidth',3,'Color',dat(kk).color);
% %             plot(n(l)*[1 1],dat(kk).probn(l,j)+dat(kk).probn_sem(l,j)*[-1 1],':','LineWidth',3,'Color',dat(kk).color);
%         end
        
    end
    
    ylabel('Fraction of trials');
    xlabel('Trial from block switch');
    axis([n(1) n(end) 0 1]);
    title([rule_labels{transType(j,1)} ' to ' rule_labels{transType(j,2)}]);
    
    if j==1
        legend(h,legstring);
        legend box off;
        legend ('location','west','FontSize',14)
    end
    
end

end


